#include <atcoder/math>
#include <iostream>
#include <vector>

int main() {
    using namespace std;
    unsigned N;
    unsigned long K;
    cin >> N >> K;
    vector<unsigned> P(N);
    for (auto &p : P) {
        cin >> p;
        --p;
    }

    // 求める順列
    vector<unsigned> ans(N);
    // used[i] := i に対する答えをすでに求めていれば true
    basic_string used(N, false);
    for (unsigned i{}; i < N; ++i) if (!used[i]) {
        // i を含むサイクルを求める
        vector<unsigned> cycle;
        {
            unsigned j{i};
            while (!used[j]) {
                used[j] = true;
                cycle.push_back(j);
                j = P[j];
            }
        }
        // サイクルに対して答えを求める
        const auto cycle_length{size(cycle)};
        const auto shift{atcoder::pow_mod(2, K, cycle_length)};
        for (unsigned j{}; j < cycle_length; ++j)
            ans[cycle[j]] = cycle[(j + shift) % cycle_length];
    }

    for (const auto p : ans)
        cout << p + 1 << " ";
    cout << endl;
    return 0;
}

#include <atcoder/math>
#include <iostream>
#include <vector>

int main() {
    using namespace std;
    unsigned N;
    unsigned long K;
    cin >> N >> K;

    // φ(1), φ(2), ..., φ(N) を O(N) 時間で求める
    vector<unsigned> sieve(N + 1, 1), least_prime_factor(N + 1), primes, totient(N + 1, 1);
    for (unsigned i{2}; i <= N; ++i) {
        if (sieve[i]) {
            primes.push_back(i);
            least_prime_factor[i] = i;
            totient[i] = i - 1;
        }
        for (const auto &p : primes) {
            if (i * p > N)
                break;
            sieve[i * p] = false;
            least_prime_factor[i * p] = p;
            if (least_prime_factor[i] == p) {
                totient[i * p] = totient[i] * p;
                break;
            }
            totient[i * p] = totient[i] * (p - 1);
        }
    }

    vector<unsigned> P(N);
    for (auto &p : P) {
        cin >> p;
        --p;
    }

    // 2^K mod m を O(m) 時間で求める
    const auto safe_fast_pow{[&totient](unsigned a, unsigned long K, unsigned m) {
        return atcoder::pow_mod(a, min(K, K % totient[m] + totient[m]), m);
    }};

    vector<unsigned> ans(N), used(N);
    for (unsigned i{}; i < N; ++i) if (!used[i]) {
        vector<unsigned> cycle;
        {
            unsigned j{i};
            while (!used[j]) {
                used[j] = 1;
                cycle.push_back(j);
                j = P[j];
            }
        }
        const auto cycle_length{size(cycle)};
        const auto shift{safe_fast_pow(2, K, cycle_length)};
        for (unsigned j{}; j < cycle_length; ++j)
            ans[cycle[j]] = cycle[(j + shift) % cycle_length];
    }
    for (const auto p : ans)
        cout << p + 1 << " ";
    cout << endl;
    return 0;
}
